from leann.api import LeannSearcher, SearchResult
from pathlib import Path


def _match_single_filter(field_value: Any, operator: str, filter_value: Any) -> bool:
    """Evaluate a single metadata filter operation."""
    if operator == "==":
        return field_value == filter_value
    if operator == "!=":
        return field_value != filter_value
    if operator == ">":
        try:
            return field_value > filter_value
        except TypeError:
            return False
    if operator == ">=":
        try:
            return field_value >= filter_value
        except TypeError:
            return False
    if operator == "<":
        try:
            return field_value < filter_value
        except TypeError:
            return False
    if operator == "<=":
        try:
            return field_value <= filter_value
        except TypeError:
            return False
    if operator == "in":
        try:
            return field_value in filter_value
        except TypeError:
            return False
    if operator == "not_in":
        try:
            return field_value not in filter_value
        except TypeError:
            return False

    # Unknown operator: be conservative and treat as non-match
    return False


def _matches_metadata_filters(
    metadata: Dict[str, Any], metadata_filters: Dict[str, Dict[str, Any]]
) -> bool:
    """Return True if metadata satisfies all filters."""
    if not metadata_filters:
        return True

    for field, ops in metadata_filters.items():
        # If the field is missing, treat it as non-matching
        if field not in metadata:
            return False
        field_value = metadata.get(field)
        # All operators for this field must be satisfied (AND)
        for op, filter_value in ops.items():
            if not _match_single_filter(field_value, op, filter_value):
                return False

    # All fields/ops matched
    return True


def search_with_metadata_filtering(
    index_path: str,
    query: str,
    metadata_filters: Dict[str, Dict[str, Any]],
    top_k: int = 5,
) -> List[SearchResult]:
    """Search in an index and apply metadata filters to results.

    Args:
        index_path: Path to the LEANN index file
        query: Search query string
        metadata_filters: Dictionary of filter specifications.
            Format: {"field_name": {"operator": value}}
            Example: {"category": {"==": "tech"}, "rating": {">=": 4.0}}
        top_k: Number of results to retrieve (default: 5)

    Returns:
        List of SearchResult objects that match both the query and metadata filters

    Raises:
        FileNotFoundError: If index file is not found
    """
    path_obj = Path(index_path)
    if not path_obj.exists():
        raise FileNotFoundError(f"Index file not found: {index_path}")

    searcher = LeannSearcher(str(path_obj))
    try:
        # Retrieve more than top_k to have room for filtering; use a simple
        # heuristic multiplier to avoid many round-trips.
        initial_top_k = max(top_k * 5, top_k)
        raw_results = searcher.search(query, top_k=initial_top_k)

        filtered_results: List[SearchResult] = []
        for res in raw_results:
            metadata = getattr(res, "metadata", {}) or {}
            if _matches_metadata_filters(metadata, metadata_filters):
                filtered_results.append(res)
                if len(filtered_results) >= top_k:
                    break

        return filtered_results
    finally:
        # Ensure background resources are cleaned up
        searcher.cleanup()
