from typing import List, Dict, Any
from leann.api import PassageManager, LeannSearcher
from pathlib import Path
import json
from collections import Counter, defaultdict


def _load_metadata_index(index_path: str) -> Dict[str, Any]:
    """
    Helper to load the LEANN metadata index JSON.

    The metadata is stored alongside the index; we assume a `.meta.json` file
    next to the main index file, e.g. `index.leann.meta.json`.
    """
    index_path_obj = Path(index_path)
    # Derive metadata file path: "<index>.meta.json"
    metadata_path = index_path_obj.with_suffix(index_path_obj.suffix + ".meta.json")

    if not metadata_path.is_file():
        # Some repositories might store metadata as "<index>.meta"
        alt_metadata_path = index_path_obj.with_suffix(index_path_obj.suffix + ".meta")
        if alt_metadata_path.is_file():
            metadata_path = alt_metadata_path
        else:
            raise FileNotFoundError(f"Index metadata file not found for '{index_path}'")

    with metadata_path.open("r", encoding="utf-8") as f:
        return json.load(f)


def get_index_statistics(index_path: str) -> Dict[str, Any]:
    """Get comprehensive statistics about a LEANN index.

Args:
    index_path: Path to the LEANN index file

Returns:
    Dictionary containing:
    {
        "total_passages": total number of passages,
        "metadata_fields": list of unique metadata field names,
        "field_value_counts": dictionary of field value counts
    }

Raises:
    FileNotFoundError: If index metadata file is not found"""
    # Load metadata index (JSON) for the given LEANN index
    metadata_index = _load_metadata_index(index_path)

    # Expect metadata_index to be a list of passage entries or a dict with "passages"
    if isinstance(metadata_index, dict) and "passages" in metadata_index:
        passages = metadata_index["passages"]
    else:
        passages = metadata_index

    total_passages = len(passages)

    metadata_fields = set()
    field_value_counts: Dict[str, Counter] = defaultdict(Counter)

    for passage in passages:
        # Each passage is expected to have a "metadata" dict
        metadata = passage.get("metadata", {})
        if not isinstance(metadata, dict):
            continue

        for key, value in metadata.items():
            metadata_fields.add(key)
            # Convert non-hashable or complex values to string for counting
            if isinstance(value, (dict, list)):
                value_repr = json.dumps(value, sort_keys=True)
            else:
                value_repr = str(value)
            field_value_counts[key][value_repr] += 1

    # Convert Counters to regular dicts for JSON serializability
    field_value_counts_dict: Dict[str, Dict[str, int]] = {
        field: dict(counter) for field, counter in field_value_counts.items()
    }

    return {
        "total_passages": total_passages,
        "metadata_fields": sorted(metadata_fields),
        "field_value_counts": field_value_counts_dict,
    }


def analyze_index_coverage(index_path: str, required_fields: List[str]) -> Dict[str, Any]:
    """Analyze how well an index covers required metadata fields.

Args:
    index_path: Path to the LEANN index file
    required_fields: List of metadata field names that should be present

Returns:
    Dictionary containing:
    {
        "coverage_percentage": percentage of passages that have all required fields,
        "field_coverage": dictionary mapping field name to coverage percentage,
        "missing_fields": list of required fields not found in any passage
    }

Raises:
    FileNotFoundError: If index metadata file is not found"""
    metadata_index = _load_metadata_index(index_path)

    if isinstance(metadata_index, dict) and "passages" in metadata_index:
        passages = metadata_index["passages"]
    else:
        passages = metadata_index

    total_passages = len(passages)
    if total_passages == 0:
        # Avoid division by zero; no passages means 0 coverage everywhere
        field_coverage = {field: 0.0 for field in required_fields}
        return {
            "coverage_percentage": 0.0,
            "field_coverage": field_coverage,
            "missing_fields": list(required_fields),
        }

    # Count for each required field how many passages contain it (non-null)
    field_counts = {field: 0 for field in required_fields}
    passages_with_all_fields = 0

    for passage in passages:
        metadata = passage.get("metadata", {})
        if not isinstance(metadata, dict):
            continue

        has_all = True
        for field in required_fields:
            if field in metadata and metadata[field] is not None:
                field_counts[field] += 1
            else:
                has_all = False
        if has_all:
            passages_with_all_fields += 1

    field_coverage = {
        field: (field_counts[field] / total_passages) * 100.0
        for field in required_fields
    }

    coverage_percentage = (passages_with_all_fields / total_passages) * 100.0

    # Missing fields: those with zero occurrences across all passages
    missing_fields = [field for field, count in field_counts.items() if count == 0]

    return {
        "coverage_percentage": coverage_percentage,
        "field_coverage": field_coverage,
        "missing_fields": missing_fields,
    }

